const req=$input.first().json||{};
const body=req.body&&typeof req.body==='object'?req.body:{};
const input=String(body.input||'').trim();
if(input.length<12)throw new Error('Bitte einen Stellenlink oder eine aussagekraeftige Stellenbeschreibung einfuegen.');
if(input.length>18000)throw new Error('Eingabe zu lang (maximal 18 000 Zeichen).');
return [{json:{input}}];

const input=String($('Eingabe pruefen').first().json.input||'');
const model=$input.first().json||{};
let extracted={};
try {
  let raw='';
  if(typeof model.output_text==='string')raw=model.output_text;
  if(!raw&&Array.isArray(model.output)) {
    const messages=model.output.filter(x=>x&&x.type==='message');
    for(const m of messages)for(const c of (m.content||[]))if(typeof c.text==='string'){raw=c.text;break;}
  }
  if(!raw&&typeof model.text==='string')raw=model.text;
  if(!raw&&typeof model.content==='string')raw=model.content;
  if(!raw&&typeof model.message?.content==='string')raw=model.message.content;
  if(!raw&&Array.isArray(model.output)) {
    for(const m of model.output)for(const c of (m.content||[])) {
      if(c&&c.type==='output_text'&&c.text&&typeof c.text==='object') {extracted=c.text;break;}
    }
  }
  if(raw) {
    raw=raw.replace(/^\s*\x60{3}(?:json)?\s*/i,'').replace(/\s*\x60{3}\s*$/,'').trim();
    extracted=JSON.parse(raw);
  }
} catch(e) { extracted={company:'',careers_url:'',type:'Auto',confidence:'low',reason:'KI-Ergebnis konnte nicht sicher ausgewertet werden. Bitte manuell pruefen.',source_url:''}; }
function clean(v,max){return String(v??'').trim().slice(0,max);}
function normalize(link){
  const m=clean(link,2000).match(/^https:\/\/([a-z0-9][a-z0-9.-]*)(\/[^\s?#]*)?/i);
  if(!m)return null;
  const host=m[1].toLowerCase(),path=m[2]||'/',seg=path.split('/').filter(Boolean);
  if(host==='localhost'||host.endsWith('.local')||host.endsWith('.internal')||host.endsWith('.test')||/^\d+\.\d+\.\d+\.\d+$/.test(host)||host.indexOf('..')>=0)return null;
  const esc=s=>/^[a-z0-9_-]+$/i.test(s||'')?s:'';
  if(host==='jobs.ashbyhq.com'&&esc(seg[0]))return {url:'https://jobs.ashbyhq.com/'+seg[0],type:'Ashby',hint:seg[0]};
  if(host==='jobs.lever.co'&&esc(seg[0]))return {url:'https://jobs.lever.co/'+seg[0],type:'Lever',hint:seg[0]};
  if(host==='jobs.eu.lever.co'&&esc(seg[0]))return {url:'https://jobs.eu.lever.co/'+seg[0],type:'Lever EU',hint:seg[0]};
  if((host==='job-boards.greenhouse.io'||host==='boards.greenhouse.io')&&esc(seg[0]))return {url:'https://job-boards.greenhouse.io/'+seg[0],type:'Greenhouse',hint:seg[0]};
  if(host==='apply.workable.com'&&esc(seg[0]))return {url:'https://apply.workable.com/'+seg[0]+'/',type:'Workable',hint:seg[0]};
  if(/^[a-z0-9-]+\.recruitee\.com$/.test(host))return {url:'https://'+host+'/',type:'Recruitee',hint:host.split('.')[0]};
  return {url:'https://'+host+path,type:'HTML',hint:''};
}
const fromInput=input.match(/https:\/\/[^\s"'<>()[\]]+/i);
const direct=fromInput?normalize(fromInput[0]):null;
const canonicalDirect=direct&&direct.type!=='HTML'?direct:null;
const fromAI=normalize(extracted.careers_url);
const final=canonicalDirect||fromAI;
const types=['Auto','Greenhouse','Lever','Lever EU','Ashby','HTML','Workable','Recruitee'];
const type=final?final.type:'Auto';
let company=clean(extracted.company,140);
if(!company&&canonicalDirect){company=canonicalDirect.hint.replace(/[-_]+/g,' ').replace(/\b[a-z]/g,c=>c.toUpperCase());}
const conf=canonicalDirect?'high':(['high','medium','low'].includes(extracted.confidence)?extracted.confidence:'low');
const reason=clean(extracted.reason,700)||(canonicalDirect?'Quellen-URL direkt aus bekanntem Bewerbungslink abgeleitet. Firmenname bitte kontrollieren.':'Keine zweifelsfrei bestaetigte Karriereseite gefunden. Bitte manuell pruefen.');
const sourceUrl=normalize(extracted.source_url)?.url||'';
return [{json:{
  company,
  careers_url:final?final.url:'',
  type:types.includes(type)?type:'Auto',
  confidence:conf,
  reason,
  evidence_url:sourceUrl,
  active_suggestion:!!canonicalDirect&&['Ashby','Greenhouse','Lever','Lever EU'].includes(type)?'Ja':'Nein',
  needs_review:true
}}];
